select nsmc.* from nurse_site_maintain_config nsmc, user_org uo, org_info oi

    uo.user_uid = #{userUid} AND nsmc.tenant_uid = #{tenantUid} and uo.org_uid IN ( oi.tenant_uid, oi.hospital_uid, oi.site_uid, oi.institution_uid, oi.uid ) AND oi.org_type = 4 AND oi.uid= nsmc.clinical_dept_uid and nsmc.deleted is false






                and nsmc.tenant_uid = #{tenantUid}


                and (
                nsmc.institution_uid in

                    #{item}

                or nsmc.hospital_uid in

                    #{item}

                or nsmc.site_uid in

                    #{item}

                or nsmc.clinical_dept_uid in

                    #{item}

                )




GROUP BY nsmc.id
order by nsmc.modify_date desc

